    (1, 1, 35, 113, 57, 1, '11101001', 1, '1110100101', 0, 20, null, 20),
    (1, 1, 35, 114, 57, 3, '5201', 1, '52010127', 20, 0, 20, null),
    (1, 1, 35, 115, 58, 1, '11101001', 1, '1110100101', 0, 110.6, null, 110.6),
    (1, 1, 35, 116, 58, 3, '5201', 1, '52010127', 110.6, 0, 110.6, null),
