    (1, 1, 35, 119, 60, 1, '11101001', 1, '1110100101', 0, 10, null, 10),
    (1, 1, 35, 120, 60, 3, '5201', 1, '52010127', 10, 0, 10, null),
    (1, 1, 35, 121, 61, 1, '11101001', 1, '1110100101', 0, 100, null, 100),
    (1, 1, 35, 122, 61, 3, '5201', 1, '52010117', 100, 0, 100, null),
    (1, 1, 35, 123, 62, 1, '11101001', 1, '1110100101', 0, 12, null, 12),
